	/**
	 * Default Constructor
	 */
    public FacilityService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new FacilityEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(FacilityRepository.class) );
		this.validator		= applicationContext.getBean(FacilityValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Facility
	 */
		public Facility createFacility( CreateFacilityCommand command ) {

		Facility entity = new Facility();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setFacilityId( command.getFacilityId() );
            entity.setName( command.getName() );
            entity.setFacilityCode( command.getFacilityCode() );
            entity.setAddress( command.getAddress() );
            entity.setFacilityType( command.getFacilityType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Facility {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateFacilityCommand
	 * @return		Facility
	 */
	public Facility updateFacility( UpdateFacilityCommand command ) {

		Facility entity = new Facility();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setFacilityId( command.getFacilityId() );
            entity.setName( command.getName() );
            entity.setFacilityCode( command.getFacilityCode() );
            entity.setAddress( command.getAddress() );
            entity.setHealthSystem( command.getHealthSystem() );
            entity.setDepartments( command.getDepartments() );
            entity.setCareTeams( command.getCareTeams() );
            entity.setLaboratories( command.getLaboratories() );
            entity.setImagingCenters( command.getImagingCenters() );
            entity.setPharmacies( command.getPharmacies() );
            entity.setInventoryItems( command.getInventoryItems() );
            entity.setFacilityType( command.getFacilityType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Facility {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteFacilityCommand
	 */
	public void delete( DeleteFacilityCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getFacilityId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Facility {0} ", id );

	}

	/**
	 * Method to retrieve the Facility via FacilityFetchOneSummary
	 * @param 	summary FacilityFetchOneSummary
	 * @return 	FacilityFetchOneResponse
	 */
	public Facility getFacility( FacilityFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "FacilityFetchOneSummary arg cannot be null" );

		Facility entity = null;
		UUID id = summary.getFacilityId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Facility using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Facilitys
	 *
	 * @return 	List<Facility>
	 */
    public List<Facility> getAllFacility() {
		List<Facility> list = projector.findAll( new FindAllFacilityQuery() );
		return list;
	}

	/**
	 * assign HealthSystem on Facility
	 * @param		command AssignHealthSystemToFacilityCommand
	 */
	public void assignHealthSystem( AssignHealthSystemToFacilityCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignHealthSystem(command.getFacilityId(), command.getAssignment());

	}

